/// <reference path="./manga-provider.d.ts" />

class Provider {
    constructor() {
        this.baseUrl = "https://mangafire.to";
    }

    getSettings() {
        return {
            supportsMultiLanguage: true,
            supportsMultiScanlator: true
        };
    }

    async request(url) {
        var response = await fetch(url, {
            method: "GET",
            headers: {
                "Accept": "application/json",
                "Referer": this.baseUrl
            }
        });

        if (!response.ok) {
            throw new Error("MangaFire HTTP " + response.status);
        }

        return await response.json();
    }

    extractMangaId(url) {
        var value = String(url || "");
        value = value.split("?")[0];
        value = value.replace(/\/+$/, "");

        if (value.indexOf("/title/") >= 0) {
            var last = value.substring(value.lastIndexOf("/") + 1);
            return last.split("-")[0];
        }

        if (value.indexOf("/manga/") >= 0) {
            var legacy = value.substring(value.lastIndexOf("/") + 1);
            var dot = legacy.lastIndexOf(".");
            if (dot >= 0) {
                return legacy.substring(dot + 1);
            }
        }

        return "";
    }

    async search(opts) {
        var url =
            this.baseUrl +
            "/api/titles?keyword=" +
            encodeURIComponent(opts.query) +
            "&language=en&limit=30&page=1";

        var json = await this.request(url);
        var items = json && Array.isArray(json.items) ? json.items : [];
        var results = [];

        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            var mangaUrl = item && item.url ? String(item.url) : "";
            var id = this.extractMangaId(mangaUrl);

            if (!id) {
                continue;
            }

            var image = undefined;
            if (item.poster && typeof item.poster === "object") {
                image =
                    item.poster.medium ||
                    item.poster.large ||
                    item.poster.small;
            }

            results.push({
                id: id,
                title: item.title ? String(item.title) : "",
                synonyms: [],
                image: image
            });
        }

        return results;
    }

    async findChapters(mangaId) {
        var chapters = [];
        var seen = {};
        var page = 1;
        var hasNext = true;

        while (hasNext && page <= 100) {
            var url =
                this.baseUrl +
                "/api/titles/" +
                encodeURIComponent(mangaId) +
                "/chapters" +
                "?language=en&sort=number&order=desc&limit=200&page=" +
                page;

            var json = await this.request(url);
            var items = json && Array.isArray(json.items) ? json.items : [];

            for (var i = 0; i < items.length; i++) {
                var item = items[i];
                var chapterId = item && item.id != null
                    ? String(item.id)
                    : "";

                if (!chapterId || seen[chapterId]) {
                    continue;
                }

                seen[chapterId] = true;

                var number = item.number != null
                    ? String(item.number)
                    : "";

                var title = "Chapter";
                if (number) {
                    title = "Ch. " + number;
                }
                if (item.name) {
                    title += ": " + String(item.name);
                }

                chapters.push({
                    id: chapterId,
                    url: this.baseUrl + "/title/" +
                        encodeURIComponent(mangaId) +
                        "/" + encodeURIComponent(chapterId),
                    title: title,
                    chapter: number,
                    index: 0,
                    scanlator: item.type === "official"
                        ? "official"
                        : undefined,
                    language: item.language
                        ? String(item.language)
                        : "en",
                    updatedAt: item.createdAt
                        ? new Date(Number(item.createdAt) * 1000).toISOString()
                        : undefined
                });
            }

            hasNext = !!(
                json &&
                json.meta &&
                json.meta.hasNext === true
            );

            page++;
        }

        // MangaFire returns newest chapters first.
        // Seanime wants ascending indexes.
        chapters.reverse();

        for (var j = 0; j < chapters.length; j++) {
            chapters[j].index = j;
        }

        return chapters;
    }

    async findChapterPages(chapterId) {
        var url =
            this.baseUrl +
            "/api/chapters/" +
            encodeURIComponent(chapterId);

        var json = await this.request(url);

        if (
            !json ||
            !json.data ||
            !Array.isArray(json.data.pages)
        ) {
            return [];
        }

        var pages = [];

        for (var i = 0; i < json.data.pages.length; i++) {
            var page = json.data.pages[i];

            if (!page || !page.url) {
                continue;
            }

            pages.push({
                url: String(page.url),
                index: pages.length,
                headers: {
                    "Referer": this.baseUrl
                }
            });
        }

        return pages;
    }
}
